 IEnumerator Run(){Passed.Clear();Finished=false;Failure=null;var stack=new Stack<IEnumerator>();stack.Push(Scenario());while(stack.Count>0){bool more=false;object next=null;try{more=stack.Peek().MoveNext();if(more)next=stack.Peek().Current;}catch(Exception e){Failure=e.ToString();break;}if(!more){stack.Pop();continue;}if(next is IEnumerator){stack.Push((IEnumerator)next);continue;}yield return next;}File.WriteAllText("Docs/Phase24/FINAL_INTEGRATION.txt",string.Join("\n",Passed)+"\nFailure: "+Failure);Finished=true;Progress="Complete";Destroy(gameObject);}
